package io.knowledgebrain.collaboration;
import java.util.*;import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import org.springframework.mock.web.MockHttpServletRequest;import org.springframework.web.server.ResponseStatusException;import io.micrometer.core.instrument.simple.SimpleMeterRegistry;
class StudyReviewQueueApiTest {
 SubmissionApiTest f;StudyReviewQueueStore store;StudyReviewQueueController api;
 @BeforeEach void setup(){f=new SubmissionApiTest();f.setup();store=mock(StudyReviewQueueStore.class);api=new StudyReviewQueueController(store,f.f.api,new SimpleMeterRegistry());}
 org.springframework.http.ResponseEntity<?> get(MockHttpServletRequest r)throws Exception{return api.list(f.f.group.toString(),f.study.toString(),r);}
 void status(int code,org.junit.jupiter.api.function.Executable fn){assertEquals(code,assertThrows(ResponseStatusException.class,fn).getStatusCode().value());}
 @Test void ownerDefaultUsesFreshActorAndNoStoreWithoutWriteOrigin()throws Exception{when(store.list(f.f.group,f.f.space,f.study,null,20,"NEEDS_FEEDBACK")).thenReturn(new StudyReviewQueueStore.Page(List.of(),null));var r=f.req("GET",null);r.removeHeader("Origin");assertEquals("no-store",get(r).getHeaders().getCacheControl());verify(store).list(f.f.group,f.f.space,f.study,null,20,"NEEDS_FEEDBACK");}
 @Test void memberViewerAndRevokedGrantsCannotEnumerateAnyFilter(){for(String role:List.of("MEMBER","VIEWER")){f.f.role(role);for(String filter:StudyReviewQueueStore.FILTERS){var r=f.req("GET",null);r.addParameter("filter",filter);status(403,()->get(r));}}verifyNoInteractions(store);}
 @Test void allFiltersAndMaxCursorAreStrictlyPassedThrough()throws Exception{for(String filter:StudyReviewQueueStore.FILTERS){var r=f.req("GET",null);r.addParameter("filter",filter);r.addParameter("limit","100");r.addParameter("after",f.f.id.toString());get(r);verify(store).list(f.f.group,f.f.space,f.study,f.f.id,100,filter);}}
 @Test void unknownDuplicateQueriesInvalidBoundsAndReadBodiesAreRejected(){for(String filter:List.of("current","NEEDS_GRADING","","CURRENT,OUTDATED")){var r=f.req("GET",null);r.addParameter("filter",filter);status(400,()->get(r));}for(String limit:List.of("0","101","01","1.5")){var r=f.req("GET",null);r.addParameter("limit",limit);status(400,()->get(r));}var duplicate=f.req("GET",null);duplicate.addParameter("filter","ALL","CURRENT");status(400,()->get(duplicate));var forged=f.req("GET",null);forged.addParameter("actorId",f.f.actor.toString());status(400,()->get(forged));status(400,()->get(f.req("GET","{}")));verifyNoInteractions(store);}
 @Test void secureSingletonSessionAndFreshGroupScopePrecedeOwnDatabase(){var insecure=f.req("GET",null);insecure.setSecure(false);var duplicate=f.req("GET",null);duplicate.addHeader("Cookie","__Host-brain_guest="+f.f.token);for(var r:List.of(insecure,duplicate))assertThrows(ResponseStatusException.class,()->get(r));verifyNoInteractions(f.f.auth,store);when(f.f.auth.participation(any(),anyList(),anyString())).thenReturn(new GroupSpaceClient.Access(f.f.actor,"REGISTERED",List.of()));status(404,()->get(f.req("GET",null)));verifyNoInteractions(store);}
}
